options=read('/input/options')
ids=[o['id'] for o in options]
from itertools import combinations
result=[]
for c in combinations(ids,3):
 valid_combo=True
 workers=set()
 jobs=set()
 for cid in c:
  opt=None
  for o in options:
   if o['id']==cid:
    opt=o
    break
  if opt is None:
   valid_combo=False
   break
  if opt['worker'] in workers or opt['job'] in jobs:
   valid_combo=False
   break
  workers.add(opt['worker'])
  jobs.add(opt['job'])
 if not valid_combo:
  continue
 # Check coverage
 cover=goal['cover']
 covers_met=True
 for field in cover:
  vals=set([opt[field] for opt in options if opt['id'] in c])
  for val in cover[field]:
   if val not in vals:
    covers_met=False
    break
  if not covers_met:
   break
 if not covers_met:
  continue
 # Check requires
 if goal['closed_dependencies']:
  # For each selected option, all requires must be in selection
  for cid in c:
   opt=None
   for o in options:
    if o['id']==cid:
     opt=o
     break
   for req in opt['requires']:
    if req not in c:
     valid_combo=False
     break
   if not valid_combo:
    break
  if not valid_combo:
   continue
 # Check conflicts
 if goal['no_conflicts']:
  conflict_found=False
  for cid in c:
   opt=None
   for o in options:
    if o['id']==cid:
     opt=o
     break
   for conf in opt['conflicts']:
    if conf in c:
     conflict_found=True
     break
   if conflict_found:
    break
  if conflict_found:
   continue
 # Check sum_bounds
 sum_bounds=goal['sum_bounds']
 sum_ok=True
 for field in sum_bounds:
  vals=[opt[field] for opt in options if opt['id'] in c]
  s=sum(vals)
  if 'min' in sum_bounds[field]:
   if s<sum_bounds[field]['min']:
    sum_ok=False
    break
  if 'max' in sum_bounds[field]:
   if s>sum_bounds[field]['max']:
    sum_ok=False
    break
 if not sum_ok:
  continue
 # Check count
 if len(c)<goal['min_count'] or len(c)>goal['max_count']:
  continue
 # Check unique
 unique_fields=goal['unique']
 unique_ok=True
 for field in unique_fields:
  vals=[opt[field] for opt in options if opt['id'] in c]
  if len(vals)!=len(set(vals)):
   unique_ok=False
   break
 if not unique_ok:
  continue
 result=list(c)
 break

